sources.coarse/draw.hlsli:
#ifndef TILEINK_HLSL_COARSE_DRAW_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_DRAW_HLSLI_INCLUDED

#include "../constants.hlsli"
#include "../draw_records.hlsli"
#include "../scene_records.hlsli"
#include "tags.hlsli"

struct CoarseDraw {
    uint path_id, glyph_run_id, sdf_offset, sdf_len, shadow_offset, tag, fill_rule;
    int4 pixel_bounds;
    float4 affine_linear;
    float2 translation;
};
CoarseDraw load_draw(ByteAddressBuffer records, uint index) {
    uint base = index * DRAW_RECORD_STRIDE;
    CoarseDraw draw;
    draw.path_id = records.Load(base + DRAW_PATH);
    draw.glyph_run_id = records.Load(base + DRAW_GLYPH_RUN);
    draw.sdf_offset = records.Load(base + DRAW_SDF);
    draw.sdf_len = records.Load(base + DRAW_SDF_LEN);
    draw.shadow_offset = records.Load(base + DRAW_SHADOW);
    draw.tag = records.Load(base + DRAW_TAG);
    draw.fill_rule = records.Load(base + DRAW_FILL_RULE);
    draw.pixel_bounds = asint(records.Load4(base + DRAW_PIXEL_BOUNDS));
    draw.affine_linear = asfloat(records.Load4(base + DRAW_TRANSFORM));
    draw.translation = asfloat(records.Load2(base + DRAW_TRANSFORM + AFFINE_TRANSLATION));
    return draw;
}
bool draw_has_sdf(CoarseDraw draw) { return draw.sdf_offset != INVALID_INDEX || draw.shadow_offset != INVALID_INDEX; }
uint tile_min(int pixel, uint limit) { return pixel > 0 ? min(uint(pixel) / TILE_SIZE, limit) : 0u; }
uint tile_max(int pixel, uint limit) { return pixel > 0 ? min((uint(pixel) + TILE_SIZE - 1u) / TILE_SIZE, limit) : 0u; }
bool draw_hits_tile(CoarseDraw draw, uint2 tile, uint2 dimensions) {
    uint2 lower = uint2(tile_min(draw.pixel_bounds.x, dimensions.x), tile_min(draw.pixel_bounds.y, dimensions.y));
    uint2 upper = uint2(tile_max(draw.pixel_bounds.z, dimensions.x), tile_max(draw.pixel_bounds.w, dimensions.y));
    return all(tile >= lower) && all(tile < upper);
}
uint draw_backdrop(ByteAddressBuffer paths, CoarseDraw draw, uint2 tile, uint2 dimensions) {
    uint path_bytes; paths.GetDimensions(path_bytes);
    if (draw.path_id == INVALID_INDEX || draw.tag > DRAW_PATH_GLYPH || draw.path_id >= path_bytes / PATH_RECORD_STRIDE || !draw_hits_tile(draw, tile, dimensions)) return INVALID_INDEX;
    uint base = draw.path_id * PATH_RECORD_STRIDE;
    uint4 bbox = paths.Load4(base + PATH_BBOX);
    if (bbox.z <= bbox.x || any(tile < bbox.xy) || any(tile >= bbox.zw)) return INVALID_INDEX;
    return paths.Load(base + PATH_DATA_OFFSET) + (tile.y - bbox.y) * (bbox.z - bbox.x) + tile.x - bbox.x;
}
float2 draw_point(CoarseDraw draw, float2 position) {
    return float2(draw.affine_linear.x * position.x + draw.affine_linear.z * position.y + draw.translation.x,
                  draw.affine_linear.y * position.x + draw.affine_linear.w * position.y + draw.translation.y);
}
bool transformed_rect_hits_tile(CoarseDraw draw, int4 rect, uint2 tile) {
    float2 p0 = draw_point(draw, float2(rect.xy));
    float2 p1 = draw_point(draw, float2(rect.zy));
    float2 p2 = draw_point(draw, float2(rect.xw));
    float2 p3 = draw_point(draw, float2(rect.zw));
    float2 lower = min(min(p0, p1), min(p2, p3));
    float2 upper = max(max(p0, p1), max(p2, p3));
    float2 tile_lower = float2(tile * TILE_SIZE);
    return all(lower < tile_lower + float(TILE_SIZE)) && all(upper > tile_lower);
}

#endif // TILEINK_HLSL_COARSE_DRAW_HLSLI_INCLUDED

sources.coarse/draw_list.hlsli:
#ifndef TILEINK_HLSL_COARSE_DRAW_LIST_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_DRAW_LIST_HLSLI_INCLUDED

#include "../constants.hlsli"
#include "../coarse_records.hlsli"
#include "config.hlsli"
#include "emit_layout.hlsli"
#include "tags.hlsli"

uint draw_index_base(ConstantBuffer<CoarseConfig> settings) { return tile_draw_base(settings, settings.tile_count); }
uint draw_page_next(RWByteAddressBuffer work, ConstantBuffer<CoarseConfig> settings, uint page) {
    if ((page & DRAW_FLAT_FLAG) != 0u) return page + COARSE_WORKGROUP_SIZE;
    return work.Load(draw_index_base(settings) + page * (COARSE_WORKGROUP_SIZE + 1u) * 4u);
}
uint draw_page_index(RWByteAddressBuffer work, ConstantBuffer<CoarseConfig> settings, uint page, uint slot) {
    uint index = (page & DRAW_FLAT_FLAG) != 0u ? (page & DRAW_FLAT_MASK) + slot : page * (COARSE_WORKGROUP_SIZE + 1u) + 1u + slot;
    return work.Load(draw_index_base(settings) + index * 4u);
}
uint draw_page_at(RWByteAddressBuffer work, ConstantBuffer<CoarseConfig> settings, uint tile, uint local_page) {
    uint page = work.Load(tile_draw_base(settings, tile));
    if ((page & DRAW_FLAT_FLAG) != 0u) return page + local_page * COARSE_WORKGROUP_SIZE;
    for (uint index=0u; index < local_page && page != INVALID_INDEX; index++) page = draw_page_next(work, settings, page);
    return page;
}
void store_tile_counts(RWByteAddressBuffer work, ConstantBuffer<CoarseConfig> settings, uint tile, uint2 count) {
    work.Store(tile * COARSE_TILE_RECORD_STRIDE, count.x);
    work.Store(tile * COARSE_TILE_RECORD_STRIDE + COARSE_TILE_GLYPH_COUNT, count.y);
    uint kind_base = emit_base(settings, settings.emit_chunk_capacity);
    work.Store(kind_base + tile * 4u, count.x > 0u ? TILE_KIND_INTERPRETER : TILE_KIND_EMPTY);
}

#endif // TILEINK_HLSL_COARSE_DRAW_LIST_HLSLI_INCLUDED

sources.coarse/emit_layout.hlsli:
#ifndef TILEINK_HLSL_COARSE_EMIT_LAYOUT_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_EMIT_LAYOUT_HLSLI_INCLUDED

#include "config.hlsli"
#include "../coarse_records.hlsli"
// Byte offsets through the packed coarse work buffer; preceding regions remain intact.
uint tile_draw_base(ConstantBuffer<CoarseConfig> layout, uint tile) {
    return layout.tile_count * COARSE_TILE_RECORD_STRIDE + layout.ptcl_capacity * COARSE_PTCL_RECORD_STRIDE +
        layout.glyph_capacity * 4u + tile * COARSE_TILE_DRAW_RECORD_STRIDE;
}
uint tile_emit_base(ConstantBuffer<CoarseConfig> layout, uint tile) {
    return tile_draw_base(layout, layout.tile_count) + layout.tile_draw_index_count * 4u + tile * COARSE_TILE_EMIT_RECORD_STRIDE;
}
uint emit_base(ConstantBuffer<CoarseConfig> layout, uint reference) {
    return tile_emit_base(layout, layout.tile_count) + reference * COARSE_EMIT_RECORD_STRIDE;
}

#endif // TILEINK_HLSL_COARSE_EMIT_LAYOUT_HLSLI_INCLUDED

sources.coarse/particle_counts.hlsl:
#include "../coarse_records.hlsli"
#include "../constants.hlsli"
#include "../dispatch.hlsli"
#include "config.hlsli"
#include "classify.hlsli"
#include "draw_list.hlsli"
#include "prefix_scan.hlsli"

ConstantBuffer<CoarseConfig> config : register(b0, space0);
ConstantBuffer<DispatchGrid> dispatch_grid : register(b31, space0);
ByteAddressBuffer draw_records : register(t1, space0);
ByteAddressBuffer text_blob : register(t2, space0);
ByteAddressBuffer path_records : register(t3, space0);
ByteAddressBuffer backdrops : register(t4, space0);
ByteAddressBuffer segment_ranges : register(t5, space0);
ByteAddressBuffer layer_stack : register(t6, space0);
RWByteAddressBuffer coarse_work : register(u7, space0);
ByteAddressBuffer sdf_blob : register(t9, space0);
ByteAddressBuffer draw_batch_ids : register(t10, space0);

[numthreads(COARSE_WORKGROUP_SIZE, 1, 1)]
void coarse_emit_chunk_particle_counts(uint3 group : SV_GroupID, uint3 local : SV_GroupThreadID) {
    if (config.tile_count == 0u) return;
    uint reference = linear_group(group, uint2(dispatch_grid.x, dispatch_grid.y));
    // Prefix allocation makes tile ranges contiguous. Capacity is not the live
    // count: padded groups must not process stale records in a reused buffer.
    uint2 last_range = coarse_work.Load2(tile_emit_base(config, config.tile_count - 1u));
    if (reference >= last_range.x + last_range.y) return;
    uint base = emit_base(config, reference);
    uint2 chunk = coarse_work.Load2(base);
    uint2 position = uint2(chunk.x % config.tiles_width, chunk.x / config.tiles_width);
    uint wrappers = stack_wrapper_count(config, layer_stack, draw_records, path_records, backdrops, segment_ranges, sdf_blob, position);
    uint page = draw_page_at(coarse_work, config, chunk.x, chunk.y);
    uint ordinal = chunk.y * COARSE_WORKGROUP_SIZE + local.x;
    uint draw_count = coarse_work.Load(tile_draw_base(config, chunk.x) + COARSE_TILE_DRAW_COUNT);
    uint2 count = uint2(0u, 0u);
    if (wrappers != INVALID_INDEX && page != INVALID_INDEX && ordinal < draw_count) {
        uint draw_index = draw_page_index(coarse_work, config, page, local.x);
        count = draw_particle_count(config, draw_records, text_blob, path_records, backdrops, segment_ranges, draw_batch_ids, draw_index, position);
    }
    uint2 total;
    exclusive_prefix(count, local.x, total);
    if (local.x == 0u) {
        coarse_work.Store(base + COARSE_EMIT_PTCL_COUNT, total.x);
        coarse_work.Store(base + COARSE_EMIT_GLYPH_COUNT, total.y);
    }
}

sources.coarse/prefix_scan.hlsli:
#ifndef TILEINK_HLSL_COARSE_PREFIX_SCAN_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_PREFIX_SCAN_HLSLI_INCLUDED

#include "../constants.hlsli"
// Particle and glyph allocation use the same ordered, wrapping-u32 scan.
// Workgroup scratch is private to this helper; both prefix and total are explicit outputs.
groupshared uint2 coarse_prefix_scratch[COARSE_WORKGROUP_SIZE];
groupshared uint2 coarse_prefix_total;

uint2 exclusive_prefix(uint2 value, uint lane, out uint2 total) {
    coarse_prefix_scratch[lane] = value;
    GroupMemoryBarrierWithGroupSync();
    for (uint upsweep_step = 1u; upsweep_step < COARSE_WORKGROUP_SIZE; upsweep_step *= 2u) {
        uint index = (lane + 1u) * upsweep_step * 2u - 1u;
        if (index < COARSE_WORKGROUP_SIZE) coarse_prefix_scratch[index] += coarse_prefix_scratch[index - upsweep_step];
        GroupMemoryBarrierWithGroupSync();
    }
    if (lane == 0u) {
        coarse_prefix_total = coarse_prefix_scratch[COARSE_WORKGROUP_SIZE - 1u];
        coarse_prefix_scratch[COARSE_WORKGROUP_SIZE - 1u] = uint2(0u, 0u);
    }
    GroupMemoryBarrierWithGroupSync();
    for (uint downsweep_step = COARSE_WORKGROUP_SIZE / 2u; downsweep_step > 0u; downsweep_step /= 2u) {
        uint index = (lane + 1u) * downsweep_step * 2u - 1u;
        if (index < COARSE_WORKGROUP_SIZE) {
            uint left = index - downsweep_step;
            uint2 previous = coarse_prefix_scratch[left];
            coarse_prefix_scratch[left] = coarse_prefix_scratch[index];
            coarse_prefix_scratch[index] += previous;
        }
        GroupMemoryBarrierWithGroupSync();
    }
    uint2 result = coarse_prefix_scratch[lane];
    total = coarse_prefix_total;
    GroupMemoryBarrierWithGroupSync();
    return result;
}

#endif // TILEINK_HLSL_COARSE_PREFIX_SCAN_HLSLI_INCLUDED

sources.coarse/sdf_clip.hlsli:
#ifndef TILEINK_HLSL_COARSE_SDF_CLIP_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_SDF_CLIP_HLSLI_INCLUDED

#include "draw.hlsli"

static const float FULL_TILE_SDF_INSET = 0.5;
bool rounded_corner_covers(float2 position, float2 corner, float2 center, float radius) {
    bool in_square = radius > 0.0 && all(abs(position - corner) < radius);
    float inner_radius = radius - FULL_TILE_SDF_INSET;
    float2 delta = position - center;
    return !in_square || (inner_radius > 0.0 && dot(delta, delta) <= inner_radius * inner_radius);
}
bool sdf_clip_covers(ByteAddressBuffer sdf, CoarseDraw draw, uint2 tile) {
    if (draw.sdf_offset == INVALID_INDEX || draw.shadow_offset != INVALID_INDEX || draw.sdf_len < 9u) return false;
    uint base = draw.sdf_offset * 4u;
    if (sdf.Load(base) != SDF_RECT || any(draw.affine_linear != float4(1.0, 0.0, 0.0, 1.0))) return false;
    float4 rect = asfloat(sdf.Load4(base + 4u));
    float2 lower = min(rect.xy, rect.zw);
    float2 upper = max(rect.xy, rect.zw);
    float2 tile_lower = float2(tile * TILE_SIZE) + 0.5 - draw.translation;
    float2 tile_upper = tile_lower + float(TILE_SIZE - 1u);
    float2 size = upper - lower;
    if (any(size < float(TILE_SIZE - 1u) + 2.0 * FULL_TILE_SDF_INSET) || any(tile_lower < lower + FULL_TILE_SDF_INSET) || any(tile_upper > upper - FULL_TILE_SDF_INSET)) return false;
    float limit = min(size.x, size.y) * 0.5;
    float4 radii = min(max(asfloat(sdf.Load4(base + 20u)), 0.0), limit);
    return rounded_corner_covers(tile_lower, lower, lower + radii.x, radii.x)
        && rounded_corner_covers(float2(tile_upper.x, tile_lower.y), float2(upper.x, lower.y), float2(upper.x-radii.y, lower.y+radii.y), radii.y)
        && rounded_corner_covers(float2(tile_lower.x, tile_upper.y), float2(lower.x, upper.y), float2(lower.x+radii.z, upper.y-radii.z), radii.z)
        && rounded_corner_covers(tile_upper, upper, upper-radii.w, radii.w);
}

#endif // TILEINK_HLSL_COARSE_SDF_CLIP_HLSLI_INCLUDED

